import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE 32
#define SPLIT_K 64
__global__ void matmul_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int M, int N, int K) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * TILE + ty;
    int col = blockIdx.x * TILE + tx;
    int splitIdx = blockIdx.z;
    // Divide K dimension across SPLIT_K blocks along the z-grid dimension.
    int baseChunk = K / SPLIT_K;
    int chunkStart = splitIdx * baseChunk;
    int chunkEnd = (splitIdx == SPLIT_K - 1) ? K : chunkStart + baseChunk;
    int chunkK = chunkEnd - chunkStart;
    float acc = 0.0f;
    int numTiles = chunkK / TILE; // divisible for this problem size, but guard remainder below
    for (int t = 0; t < numTiles; ++t) {
        int aCol = chunkStart + t * TILE + tx;
        int bRow = chunkStart + t * TILE + ty;
        As[ty][tx] = A[row * K + aCol];
        Bs[ty][tx] = B[bRow * N + col];
        __syncthreads();
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += As[ty][k] * Bs[k][tx];
        }
        __syncthreads();
    }
    // Handle remainder within this chunk if chunkK is not perfectly divisible by TILE
    int rem_start = chunkStart + numTiles * TILE;
    if (rem_start < chunkEnd) {
        for (int k = rem_start; k < chunkEnd; ++k) {
            acc += A[row * K + k] * B[k * N + col];
        }
    }
    if (row < M && col < N) {
        atomicAdd(&C[row * N + col], acc);
    }
}
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);
    auto C = torch::zeros({M, N}, A.options());
    dim3 block(TILE, TILE);
    int splitK = SPLIT_K;
    if (splitK > K) splitK = 1;
    dim3 grid((N + TILE - 1) / TILE, (M + TILE - 1) / TILE, splitK);
    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, K
    );
    return C;
}
"""

cpp_source = r"""
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a single matrix multiplication (C = A * B) with a large K dimension
    using a custom tiled CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_op = matmul_module

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        A = A.cuda().contiguous()
        B = B.cuda().contiguous()
        return self.matmul_op.matmul_cuda(A, B)


M = 256
N = 256
K = 131072 * 4

def get_inputs():
    A = torch.rand(M, K)
    B = torch.rand(K, N)
    return [A, B]

def get_init_inputs():
    return []

